 1	/* ============================================================
 2	   api-client.js — API Client module
 3	   Section 1 of the MCP Server Dashboard SPA
 4	   ============================================================ */
 5	
 6	var API = (function () {
 7	  async function request(method, path, body) {
 8	    var opts = {
 9	      method: method,
10	      headers: {},
11	    };
12	    if (body !== undefined) {
13	      opts.headers['Content-Type'] = 'application/json';
14	      opts.body = JSON.stringify(body);
15	    }
16	    var res = await fetch('/api' + path, opts);
17	    if (!res.ok) {
18	      var errData = null;
19	      try { errData = await res.json(); } catch (_) {}
20	      var errMsg = (errData && errData.error && errData.error.message) || ('HTTP ' + res.status);
21	      var errCode = (errData && errData.error && errData.error.code) || 'ERROR';
22	      throw { code: errCode, message: errMsg };
23	    }
24	    if (res.status === 204) return null;
25	    return res.json();
26	  }
27	
28	  /**
29	   * Serialize *params* as a URL query string.
30	   *
31	   * Keys whose value is `undefined` or an empty string (`''`) are silently
32	   * omitted from the output.  This is intentional: callers use `undefined` as
33	   * a "no filter" sentinel (e.g. `{ wp: wpId }` where `wpId` may be
34	   * `undefined`), and the omission prevents `?wp=undefined` from reaching
35	   * the server.
36	   *
37	   * @param {Record<string, any>|null|undefined} params - Key/value pairs to encode.
38	   * @returns {string} A `?key=value&…` string, or `''` when no params survive
39	   *   the filter.
40	   */
41	  function buildQueryString(params) {
42	    if (!params) return '';
43	    var parts = Object.keys(params)
44	      .filter(function (k) { return params[k] !== undefined && params[k] !== ''; })
45	      .map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); });
46	    return parts.length ? '?' + parts.join('&') : '';
47	  }
48	
49	  return {
50	    getProjects: function (params) {
51	      return request('GET', '/projects' + buildQueryString(params));
52	    },
53	    getProject:               function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug)); },
54	    getWorkPackages:          function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/work-packages'); },
55	    getWorkPackage:           function (slug, wpId)   { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/work-packages/' + encodeURIComponent(wpId)); },
56	    deleteProject:            function (slug)         { return request('DELETE', '/projects/' + encodeURIComponent(slug)); },
57	    archiveProject:           function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/archive'); },
58	    unarchiveProject:         function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/unarchive'); },
59	    getConfig:                function ()             { return request('GET',    '/config'); },
60	    updateConfig:             function (data)         { return request('PUT',    '/config', data); },
61	    getInsights:              function ()             { return request('GET',    '/insights'); },
62	    getServerInfo:            function ()             { return request('GET',    '/server-info'); },
63	    getPlanDocument:          function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/plan'); },
64	    getSynthesisDocument:     function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/synthesis'); },
65	    analyzeProjectReset:      function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/reset', { dry_run: true }); },
66	    applyProjectReset:        function (slug, decisions) { return request('POST', '/projects/' + encodeURIComponent(slug) + '/reset', { dry_run: false, decisions: decisions }); },
67	    getProjectHealth:         function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/health'); },
68	    getWorkPackageOverview:   function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/work-packages/overview'); },
69	    renameProject:            function (slug, title)  { return request('PATCH',  '/projects/' + encodeURIComponent(slug), { title: title }); },
70	    renameSlug:               function (slug, newSlug) { return request('PATCH',  '/projects/' + encodeURIComponent(slug), { slug: newSlug }); },
71	    markProjectComplete:      function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/complete'); },
72	    getRunLogs:               function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/runs'); },
73	    getRunLogEntries:         function (slug, filename, afterLine) {
74	      var qs = (afterLine !== undefined && afterLine !== null) ? ('?after=' + encodeURIComponent(afterLine)) : '';
75	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/runs/' + encodeURIComponent(filename) + qs);
76	    },
77	    getDialogues: function (slug, wpId) {
78	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/dialogues' + buildQueryString({ wp: wpId }));
79	    },
80	    getDialogueContent: function (slug, filename) {
81	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/dialogues/' + encodeURIComponent(filename))
82	        .then(function (data) { return data.content; });
83	    },
84	    getChunks: function (slug, wpId) {
85	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/chunks' + buildQueryString({ wp: wpId }));
86	    },
87	    getChunkRendered: function (slug, filename) {
88	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/chunks/' + encodeURIComponent(filename) + '/rendered')
89	        .then(function (data) { return data.content; });
90	    },
91	
92	    // -- Orchestrator --------------------------------------------------
93	    orchestratorStart:       function (planPath, dryRun) { return request('POST',   '/orchestrator/start',                                         { planPath: planPath, dryRun: dryRun }); },
94	    orchestratorGetQueue:    function ()                 { return request('GET',    '/orchestrator/queue'); },
95	    orchestratorGetRunStatus: function (slug)            { return request('GET',    '/orchestrator/run-status/' + encodeURIComponent(slug)); },
96	    orchestratorKill:        function (id)               { return request('POST',   '/orchestrator/kill/'       + encodeURIComponent(id)); },
97	    orchestratorDismiss:     function (id)               { return request('POST',   '/orchestrator/dismiss/'    + encodeURIComponent(id)); },
98	
99	    // -- Knowledge -----------------------------------------------------

